export const agentSocials = (t: Agent): { kind: SocialKind; href: string; label: string }[] => {
  const s = { facebook: CONTACT.facebook, instagram: CONTACT.instagram, linkedin: CONTACT.linkedin, ...(t.socials || {}) };
  return (['facebook', 'instagram', 'linkedin'] as SocialKind[]).filter(k => s[k]).map(k => ({ kind: k, href: s[k]!, label: SOCIAL_LABEL[k] }));
};

