const range = (a: number, b: number, step: number) => { const o: number[] = []; for (let v = a; v <= b; v += step) o.push(v); return o; };
const money = (n: number) => n >= 1000000 ? '$' + (n / 1000000).toFixed(n % 1000000 ? 2 : 0) + 'M' : '$' + n.toLocaleString('en-AU');
